def transform(grid):
    h, w = len(grid), len(grid[0])
    # Identify the horizontal divider and the two objects below it.
    div = next(r for r, row in enumerate(grid) if all(v == 5 for v in row))
    below = {}
    for r in range(div + 1, h):
        for c, v in enumerate(grid[r]):
            if v:
                below.setdefault(v, []).append((r, c))
    base = below[1]
    upper_colors = {}
    for r in range(div):
        for c, v in enumerate(grid[r]):
            if v not in (0, 1, 2):
                upper_colors.setdefault(v, []).append((r, c))
    color = next(iter(upper_colors))
    shape = upper_colors[color]

    out = [[0] * w for _ in range(9)]
    br0 = min(r for r, c in base)
    bc0, bc1 = min(c for r, c in base), max(c for r, c in base)
    for r, c in base:
        rr = r - 6
        if 0 <= rr < 9:
            out[rr][c] = 1

    sr0, sr1 = min(r for r, c in shape), max(r for r, c in shape)
    sc0, sc1 = min(c for r, c in shape), max(c for r, c in shape)
    base_top = br0 - 6
    shape_top = base_top - (sr1 - sr0 + 1)
    base_center = (bc0 + bc1) / 2
    shape_center = (sc0 + sc1) / 2
    dc = round(base_center - shape_center)
    for r, c in shape:
        rr = shape_top + (r - sr0)
        cc = c + dc
        if 0 <= rr < 9 and 0 <= cc < w:
            out[rr][cc] = color
    return out
